package com.meetspace.repository; import com.meetspace.dto.BookingDtos.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.time.*; import java.util.*;
@Repository public class BookingRepository{private final JdbcTemplate j;public BookingRepository(JdbcTemplate j){this.j=j;}private Response row(java.sql.ResultSet r)throws java.sql.SQLException{return new Response(UUID.fromString(r.getString("id")),UUID.fromString(r.getString("room_id")),r.getObject("booking_date",LocalDate.class),r.getObject("start_time",LocalTime.class),r.getObject("end_time",LocalTime.class),r.getString("purpose"),r.getString("status"));}public boolean overlap(UUID room,LocalDate date,LocalTime start,LocalTime end){return Boolean.TRUE.equals(j.queryForObject("select exists(select 1 from bookings where room_id=? and booking_date=? and status in ('PENDING','CONFIRMED') and start_time < ? and end_time > ?)",Boolean.class,room,date,end,start));}public Response create(UUID employee,Create x){UUID id=UUID.randomUUID();j.update("insert into bookings(id,employee_id,room_id,booking_date,start_time,end_time,purpose,status) values(?,?,?,?,?,?,?,'CONFIRMED')",id,employee,x.roomId(),x.bookingDate(),x.startTime(),x.endTime(),x.purpose().trim());return byId(id).orElseThrow();}public Optional<Response> owned(UUID id,UUID employee){return j.query("select id,room_id,booking_date,start_time,end_time,purpose,status from bookings where id=? and employee_id=?",(r,n)->row(r),id,employee).stream().findFirst();}public boolean cancel(UUID id,UUID employee){return j.update("update bookings set status='CANCELLED' where id=? and employee_id=? and status in ('PENDING','CONFIRMED')",id,employee)>0;}public Optional<Response> byId(UUID id){return j.query("select id,room_id,booking_date,start_time,end_time,purpose,status from bookings where id=?",(r,n)->row(r),id).stream().findFirst();}public List<Response> byEmployee(UUID emp){return j.query("select id,room_id,booking_date,start_time,end_time,purpose,status from bookings where employee_id=? order by booking_date,start_time",(r,n)->row(r),emp);}}